export const TIMETABLE = "// Turns the weekly pattern into the resolved timetable the phone follows: absolute instants for the next `days` days.\n// The phone does no calendar or time-zone logic (see schema `segments`); this runs in the parent's browser and in tests.\n\n// UTC instant of local wall-clock (y, m, d, minute-of-day) in an IANA zone. Handles DST by correcting the guess with the zone's real offset.\nexport function zonedToUtc(y, m, d, minute, tz) {\n  const fmt = new Intl.DateTimeFormat(\"en-GB\", { timeZone: tz, hourCycle: \"h23\", year: \"numeric\", month: \"numeric\", day: \"numeric\", hour: \"numeric\", minute: \"numeric\", second: \"numeric\" });\n  const offsetAt = (utc) => { const p = Object.fromEntries(fmt.formatToParts(new Date(utc)).map((x) => [x.type, +x.value])); return Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second) - utc; };\n  const wall = Date.UTC(y, m - 1, d, 0, minute);\n  let utc = wall - offsetAt(wall);\n  utc = wall - offsetAt(utc);\n  return utc;\n}\n\nconst todayIn = (tz, nowMs) => { const p = Object.fromEntries(new Intl.DateTimeFormat(\"en-GB\", { timeZone: tz, year: \"numeric\", month: \"numeric\", day: \"numeric\" }).formatToParts(new Date(nowMs)).map((x) => [x.type, +x.value])); return { y: p.year, m: p.month, d: p.day }; };\n\nexport function resolveSegments(pattern, nowMs = Date.now(), days = 14) {\n  const out = [], { y, m, d } = todayIn(pattern.tz, nowMs);\n  for (let i = 0; i < days; i++) {\n    const day = new Date(Date.UTC(y, m - 1, d + i));               // calendar arithmetic only; the zone is applied below\n    const iso = day.getUTCDay() === 0 ? 7 : day.getUTCDay();\n    const blocks = [...(pattern.days[String(iso)] ?? [])].sort((a, b) => a[0] - b[0]);\n    for (const [start, end, mode] of blocks) {\n      const from = zonedToUtc(day.getUTCFullYear(), day.getUTCMonth() + 1, day.getUTCDate(), start, pattern.tz);\n      const to = end >= 1440 ? zonedToUtc(day.getUTCFullYear(), day.getUTCMonth() + 1, day.getUTCDate() + 1, 0, pattern.tz) : zonedToUtc(day.getUTCFullYear(), day.getUTCMonth() + 1, day.getUTCDate(), end, pattern.tz);\n      if (to > nowMs && to > from) out.push({ from, to, mode });\n    }\n  }\n  return out;\n}\n\n// Problems a parent should hear about before saving: overlaps, unknown modes, backwards times.\nexport function checkPattern(pattern, modes) {\n  const problems = [];\n  for (const [day, blocks] of Object.entries(pattern.days)) {\n    const sorted = [...blocks].sort((a, b) => a[0] - b[0]);\n    sorted.forEach(([s, e, mode], i) => {\n      if (e <= s) problems.push(`Day ${day}: a block ends before it starts`);\n      if (!(mode in modes)) problems.push(`Day ${day}: unknown mode \"${mode}\"`);\n      if (i && s < sorted[i - 1][1]) problems.push(`Day ${day}: two blocks overlap`);\n    });\n  }\n  return problems;\n}\n";
export const SPOTIFY = "// Spotify sign-in for the family's OWN Spotify developer app (PKCE: no client secret). Runs in the parent's browser; the refresh token is\n// sealed to the phone before it leaves the browser, so the Worker and Cloudflare only ever hold ciphertext.\nimport { seal } from \"/seal.js\";\n\nexport const SCOPES = [\"user-read-playback-state\", \"user-modify-playback-state\", \"user-read-currently-playing\", \"streaming\", \"playlist-read-private\", \"user-library-read\"];\nexport const SLOT = \"spotify.refresh\";\nconst b64url = (buf) => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\\+/g, \"-\").replace(/\\//g, \"_\").replace(/=+$/, \"\");\n\nexport async function makePkce(rand = crypto.getRandomValues.bind(crypto)) {\n  const verifier = b64url(rand(new Uint8Array(48)));              // 64 characters, inside the 43-128 PKCE range\n  const challenge = b64url(await crypto.subtle.digest(\"SHA-256\", new TextEncoder().encode(verifier)));\n  return { verifier, challenge };\n}\n\nexport const redirectUri = (origin) => `${origin}/spotify/callback`;\n\nexport function authorizeUrl({ clientId, origin, challenge, state, scopes = SCOPES }) {\n  const u = new URL(\"https://accounts.spotify.com/authorize\");\n  u.search = new URLSearchParams({ client_id: clientId, response_type: \"code\", redirect_uri: redirectUri(origin), code_challenge_method: \"S256\", code_challenge: challenge, state, scope: scopes.join(\" \") }).toString();\n  return u.toString();\n}\n\nexport async function exchangeCode({ clientId, origin, code, verifier, fetchImpl = fetch }) {\n  const r = await fetchImpl(\"https://accounts.spotify.com/api/token\", { method: \"POST\", headers: { \"content-type\": \"application/x-www-form-urlencoded\" }, body: new URLSearchParams({ grant_type: \"authorization_code\", code, redirect_uri: redirectUri(origin), client_id: clientId, code_verifier: verifier }).toString() });\n  const j = await r.json().catch(() => ({}));\n  if (!r.ok || !j.refresh_token) throw new Error(j.error_description ?? j.error ?? \"Spotify did not accept the sign-in\");\n  return j.refresh_token;\n}\n\n// Seals the refresh token to the phone and stores it in that phone's settings (other settings are kept as they are).\nexport async function storeRefreshToken({ api, did, refreshToken }) {\n  const { encKey } = await api(`/devices/${did}/enckey`);\n  const sealed = await seal({ recipientSpki: encKey, did, name: SLOT, plaintext: refreshToken });\n  const { config } = await api(`/devices/${did}/config`);\n  const next = { ...config, secrets: { ...(config.secrets ?? {}), [SLOT]: sealed } }; delete next.version;\n  return api(`/devices/${did}/config`, \"POST\", next);\n}\n";
export const SEAL = "// Sealed credentials: the PARENT'S BROWSER encrypts a secret (Spotify refresh token, email password, ...) so that only the phone can read it.\n// The Worker and Cloudflare only ever see ciphertext. Runs unchanged in a browser, a Worker or Node (WebCrypto).\n//   alg = \"ECDH-P256+HKDF-SHA256+AES-256-GCM\"\n//   shared = ECDH(ephemeral private, phone ENCRYPTION public key)               (32 bytes, the raw x coordinate)\n//   key    = HKDF-SHA256(ikm = shared, salt = random 16 bytes, info = \"phoneguard-sealed-v1|<did>|<name>\") -> 32 bytes\n//   ct     = AES-256-GCM(key, iv = random 12 bytes, aad = \"<did>|<name>\", plaintext UTF-8), ciphertext followed by the 16-byte tag\n// Binding the device id and the secret's name into the key and the AAD means a sealed value cannot be moved to another device or another slot.\nimport { b64, unb64 } from \"./crypto.js\";\n\nexport const SEAL_ALG = \"ECDH-P256+HKDF-SHA256+AES-256-GCM\";\nconst enc = new TextEncoder();\nconst EC = { name: \"ECDH\", namedCurve: \"P-256\" };\n\nexport async function seal({ recipientSpki, did, name, plaintext }) {\n  const recipient = await crypto.subtle.importKey(\"spki\", unb64(recipientSpki), EC, false, []);\n  const eph = await crypto.subtle.generateKey(EC, true, [\"deriveBits\"]);\n  const shared = await crypto.subtle.deriveBits({ name: \"ECDH\", public: recipient }, eph.privateKey, 256);\n  const salt = crypto.getRandomValues(new Uint8Array(16)), iv = crypto.getRandomValues(new Uint8Array(12));\n  const ikm = await crypto.subtle.importKey(\"raw\", shared, \"HKDF\", false, [\"deriveKey\"]);\n  const key = await crypto.subtle.deriveKey({ name: \"HKDF\", hash: \"SHA-256\", salt, info: enc.encode(`phoneguard-sealed-v1|${did}|${name}`) }, ikm, { name: \"AES-GCM\", length: 256 }, false, [\"encrypt\"]);\n  const ct = await crypto.subtle.encrypt({ name: \"AES-GCM\", iv, additionalData: enc.encode(`${did}|${name}`) }, key, enc.encode(plaintext));\n  return { alg: SEAL_ALG, epk: b64(await crypto.subtle.exportKey(\"spki\", eph.publicKey)), salt: b64(salt), iv: b64(iv), ct: b64(ct) };\n}\n";
export const ENROL = "// The phone enrolment payload (see PROTOCOL-DRAFT.md \"Enrolment payload\"), built in the parent's browser. Must agree with setup-tool/engine.mjs and vectors.json.\nconst b64url = (bytes) => btoa(String.fromCharCode(...bytes)).replace(/\\+/g, \"-\").replace(/\\//g, \"_\").replace(/=+$/, \"\");\nexport async function enrolPayload({ host, token, serverKey }) {\n  const t = token.toUpperCase().replace(/[^A-Z0-9]/g, \"\");\n  const digest = new Uint8Array(await crypto.subtle.digest(\"SHA-256\", Uint8Array.from(atob(serverKey), (c) => c.charCodeAt(0)))).slice(0, 16);\n  return { qr: `phoneguard://enrol?v=1&h=${host}&t=${t}&f=${b64url(digest)}`, address: host.endsWith(\".workers.dev\") ? host.slice(0, -\".workers.dev\".length) : host, code: `${t.slice(0, 5)}-${t.slice(5)}` };\n}\n";
